from __future__ import annotations

import pytest

from llm_router import Provider
from llm_router._internal.providers.aistudio import adapter_from_config
from llm_router._internal.providers.registry import register_adapter_factory

pytestmark = pytest.mark.verification_kind("unit")


@pytest.mark.verifies("TREQ_OPENAI_ADAPTER_BOUNDARY[revision==1]")
@pytest.mark.parametrize(
    "provider",
    [Provider.OPENROUTER, Provider.GROQ, Provider.MISTRAL, Provider.NVIDIA],
)
def test_openai_compatible_provider_has_registered_factory(
    provider: Provider,
) -> None:
    with pytest.raises(Exception, match=r"(?i)regist|already|duplicate|exist"):
        register_adapter_factory(provider, adapter_from_config)
